import{_ as o,a0 as a,w as l,s as c,ao as r,I as n,x as e,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8","title":"如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit","tag":"201910","desc":""},"relativePath":"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8.md"};function h(k,t,g,u,C,m){const s=a("Link");return l(),c("div",null,[t[15]||(t[15]=r(`<h1 id="如何在-centos-8-rhel-8-上安裝和使用-cockpit" tabindex="-1">如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安裝和使用-cockpit" aria-label="Permalink to “如何在 CentOS 8/RHEL 8 上安裝和使用 Cockpit”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/12/093405gb8hv3exdbsdyfda.jpg" alt=""></p><p>Cockpit 是一個基於 Web 的服務器管理工具，可用於 CentOS 和 RHEL 系統。最近發佈的 CentOS 8 和 RHEL 8，其中 cockpit 是默認的服務器管理工具。它的軟件包在默認的 CentOS 8 和 RHEL 8 倉庫中就有。Cockpit 是一個有用的基於 Web 的 GUI 工具，系統管理員可以通過該工具監控和管理 Linux 服務器，它還可用於管理服務器、容器、虛擬機中的網絡和存儲，以及檢查系統和應用的日誌。</p><p>在本文中，我們將演示如何在 CentOS 8 和 RHEL 8 中安裝和設置 Cockpit。</p><h3 id="在-centos-8-rhel-8-上安裝和設置cockpit" tabindex="-1">在 CentOS 8/RHEL 8 上安裝和設置Cockpit <a class="header-anchor" href="#在-centos-8-rhel-8-上安裝和設置cockpit" aria-label="Permalink to “在 CentOS 8/RHEL 8 上安裝和設置Cockpit”">​</a></h3><p>登錄你的 CentOS 8/RHEL 8，打開終端並執行以下 <code>dnf</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install cockpit -y</span></span></code></pre></div><p>運行以下命令啓用並啓動 cockpit 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start cockpit.socket</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl enable cockpit.socket</span></span></code></pre></div><p>使用以下命令在系統防火牆中允許 Cockpit 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=cockpit</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span></code></pre></div><p>驗證 cockpit 服務是否已啓動和運行，執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl status cockpit.socket</span></span>
<span class="line"><span>[root@linuxtechi ~]# ss -tunlp | grep cockpit</span></span>
<span class="line"><span>[root@linuxtechi ~]# ps auxf|grep cockpit</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/cockpit-status-centos8-rhel8.jpg" alt="cockpit-status-centos8-rhel8"></p><h3 id="在-centos-8-rhel-8-上訪問-cockpit" tabindex="-1">在 CentOS 8/RHEL 8 上訪問 Cockpit <a class="header-anchor" href="#在-centos-8-rhel-8-上訪問-cockpit" aria-label="Permalink to “在 CentOS 8/RHEL 8 上訪問 Cockpit”">​</a></h3><p>正如我們在上面命令的輸出中看到的，cockpit 正在監聽 tcp 9090 端口，打開你的 Web 瀏覽器並輸入 url：<code>https://&lt;Your-CentOS8/RHEL8-System-IP&gt;:9090</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-cockpit-login-screen.jpg" alt="CentOS8-cockpit-login-screen"></p><p>RHEL 8 中的 Cockpit 登錄頁面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/RHEL8-Cockpit-Login-Screen.jpg" alt="RHEL8-Cockpit-Login-Screen"></p><p>使用有管理員權限的用户名，或者我們也可以使用 root 用户的密碼登錄。如果要將管理員權限分配給任何本地用户，請執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# usermod -G wheel pkumar</span></span></code></pre></div><p>這裏 <code>pkumar</code> 是我的本地用户，</p><p>在輸入用户密碼後，選擇 “Reuse my password for privileged tasks”，然後單擊 “Log In”，然後我們看到以下頁面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/cockpit-dashboard-centos8.jpg" alt="cockpit-dashboard-centos8"></p><p>在左側欄上，我們可以看到可以通過 cockpit GUI 監控和配置的內容，</p><p>假設你要檢查 CentOS 8/RHEL 8 中是否有任何可用更新，請單擊 “System Updates”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Software-Updates-Cockpit-GUI-CentOS8-RHEL8.jpg" alt="Software-Updates-Cockpit-GUI-CentOS8-RHEL8"></p><p>要安裝所有更新，點擊 “Install All Updates”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Install-Software-Updates-CentOS8-RHEL8.jpg" alt="Install-Software-Updates-CentOS8-RHEL8"></p><p>如果想要修改網絡並要添加 Bond 接口和網橋，請單擊 “Networking”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Networking-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="Networking-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>如上所見，我們有創建 Bond 接口、網橋和 VLAN 標記接口的選項。</p><p>假設我們想創建一個 <code>br0</code> 網橋，並要為它添加 <code>enp0s3</code> 端口，單擊 “Add Bridge”：</p><p>將網橋名稱指定為 <code>br0</code>，將端口指定為 <code>enp0s3</code>，然後單擊“Apply”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Add-Bridge-Cockpit-CentOS8-RHEL8.jpg" alt="Add-Bridge-Cockpit-CentOS8-RHEL8"></p><p>在下個頁面，我們將看到該網橋處於活動狀態，並且獲得了與 enp0s3 接口相同的 IP：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Bridge-Details-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="Bridge-Details-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>如果你想檢查系統日誌，單擊 “Logs”，我們可以根據嚴重性查看日誌：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/System-Logs-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="System-Logs-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>本文就是這些了，類似地，系統管理員可以使用 cockpit 的其他功能來監控和管理 CentOS 8 和 RHEL 8 服務器。如果這些步驟可以幫助你在 Linux 服務器上設置 cockpit，請在下面的評論欄分享你的反饋和意見。</p><hr>`,41)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/install-use-cockpit-tool-centos8-rhel8/"},{default:p(()=>[...t[0]||(t[0]=[e("https://www.linuxtechi.com/install-use-cockpit-tool-centos8-rhel8/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),i(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:p(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:p(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const f=o(d,[["render",h]]);export{L as __pageData,f as default};
